UPDATE `technology_deep_analysis_requests`
SET `status` = 'completed',
    `updated_at` = CURRENT_TIMESTAMP,
    `verified_through` = '2026-08-21',
    `analysis_model` = 'CHATGPT SCHEDULED ANALYSIS',
    `resolution_note` = '원출처 재확인 및 구조화 심층 분석 완료',
    `source_count` = 5,
    `result_json` = '{"executiveJudgment":"에이전트형 소프트웨어 개발은 저장소를 읽고 계획을 세운 뒤 도구로 코드를 수정하고 테스트해 변경안을 제출하는 폐루프 시스템으로 이미 제품화되었다. 그러나 현재 근거가 지지하는 범위는 경계가 명확한 저장소 작업의 위임과 검토 가능한 패치 생성까지다. 통제된 과제에서 처리 가능한 작업 길이는 늘고 있지만, 숙련 개발자가 익숙한 실제 저장소에서 수행한 무작위 연구는 2025년 초 도구 사용 시 완료 시간이 19% 늘었다. 따라서 기술의 다음 병목은 코드 생성량이 아니라 숨은 요구사항을 복원하는 문맥, 실패를 정확히 잡는 검증 오라클, 비밀값과 외부 입력을 격리하는 실행 경계, 사람이 감당할 수 있는 검토 비용이다.","technicalModel":{"systemBoundary":"사용자가 부여한 이슈 또는 작업 명세에서 시작해 저장소 복제, 관련 코드와 지침 탐색, 계획 수립, 격리된 실행 환경에서의 편집과 테스트, 브랜치와 풀 리퀘스트 제출, 사람의 검토와 병합까지를 시스템 경계로 본다. 제품 요구 결정, 조직의 책임 승인, 프로덕션 운영 결과의 최종 책임은 경계 밖에 둔다.","causalChain":[{"stage":"과제·저장소 문맥 구성","mechanism":"이슈, 코드, 테스트, 저장소 지침과 변경 이력을 검색해 실행 가능한 목표와 제약으로 바꾼다.","failureMode":"이슈에 적히지 않은 제품 규칙이나 저장소 관습을 놓치면 올바른 파일을 수정해도 실제 요구와 다른 패치를 만든다."},{"stage":"계획·도구 실행 루프","mechanism":"모델이 다음 행동을 선택하고 셸, 검색, 편집 도구를 반복 호출해 가설을 코드 변경으로 전환한다.","failureMode":"긴 작업에서 문맥이 누적 손실되거나 외부 문서의 프롬프트 인젝션과 과도한 권한이 결합하면 잘못된 행동이 실행 환경으로 전파된다."},{"stage":"실행 기반 검증","mechanism":"테스트, 린트, 타입 검사와 재현 절차를 실행해 패치가 명세를 만족하는지 확인하고 실패 시 수정 루프로 되돌린다.","failureMode":"테스트가 불완전하거나 평가 기준을 우회할 수 있으면 에이전트는 통과 신호를 얻고도 실제 결함을 남길 수 있다."},{"stage":"변경 통제·사람 검토","mechanism":"격리 브랜치와 서명된 커밋, 풀 리퀘스트, 승인된 워크플로를 통해 변경을 추적하고 사람이 병합 여부를 결정한다.","failureMode":"패치 수가 검토 역량을 넘거나 변경 근거가 불투명하면 사람 승인이 형식화되어 오류와 보안 문제가 프로덕션으로 넘어간다."}]},"evidenceInterpretation":[{"finding":"METR의 2026년 5월 공개 측정은 공개 프런티어 에이전트가 성공할 수 있는 소프트웨어 과제의 인간 작업시간 기준 길이가 장기적으로 증가했음을 보여 준다.","interpretation":"모델과 에이전트 구성의 결합이 더 긴 다단계 작업을 처리하는 방향으로 진전했다는 근거다.","limitation":"시간 지평은 모델이 실제로 그 시간 동안 자율 실행한다는 뜻이 아니며, 측정 과제의 난도와 인간 기준시간에 대한 성공 확률 추정이다. 조직별 코드베이스 생산성이나 무감독 배포 안전성을 직접 증명하지 않는다.","sourceUrls":["https://metr.org/time-horizons/"]},{"finding":"METR의 2025년 무작위 연구에서 대형 오픈소스 저장소에 익숙한 개발자 16명이 246개 실제 과제를 수행했을 때 AI 허용 조건의 완료 시간이 평균 19% 늘었다.","interpretation":"벤치마크 성능이 숙련자의 실제 생산성 향상으로 자동 전이되지 않으며 검토, 프롬프트, 대기와 수정 비용이 시스템 성능을 구속할 수 있음을 보여 준다.","limitation":"2025년 초 도구와 특정 개발자·저장소 표본의 결과다. 연구진도 2026년 후속 자료의 선택 편향 때문에 최신 도구의 효과 크기를 확정하지 못했다고 명시했다.","sourceUrls":["https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/","https://metr.org/blog/2026-02-24-uplift-update/"]},{"finding":"GitHub의 클라우드 코딩 에이전트는 격리된 실행 환경, 제한된 브랜치 쓰기, 사람 검토 전 워크플로 실행 제한과 인터넷 접근 통제를 운영 구조로 둔다.","interpretation":"현재 제품화의 핵심은 모델 단독 자율성보다 권한 최소화와 검토 가능한 변경 경로를 결합한 시스템 설계다.","limitation":"제품 문서는 통제 구조를 설명하지만 생성 패치의 정확도, 결함률 또는 조직별 순생산성 개선을 입증하는 비교 실험은 아니다.","sourceUrls":["https://docs.github.com/en/copilot/concepts/agents/cloud-agent/risks-and-mitigations","https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent"]}],"bottleneckAnalysis":[{"name":"숨은 요구사항과 저장소 문맥 복원","whyBinding":"실제 과제의 성공 조건은 이슈 본문 밖의 아키텍처 규칙, 과거 결정, 배포 관습과 이해관계자 기대에 분산돼 있다. 검색된 코드만으로 이 문맥을 복원하지 못하면 계획과 테스트가 모두 잘못된 목표를 최적화한다.","downstreamEffects":["불필요한 파일 변경과 회귀","사람의 재설명·재작업 증가","벤치마크 성공률과 실제 생산성의 괴리"],"evidenceToResolve":["동일 저장소의 반복 과제에서 문맥 기억 유무를 비교한 무작위 평가","요구사항 누락 유형별 실패 로그","사람의 수정량과 되돌림률을 포함한 장기 운영 자료"]},{"name":"검증 오라클과 권한 경계","whyBinding":"에이전트는 테스트 통과 신호를 목표로 삼지만 테스트가 실제 요구를 완전히 표현하지 못한다. 동시에 셸과 네트워크 권한이 커질수록 잘못된 판단과 프롬프트 인젝션의 피해 범위가 커진다.","downstreamEffects":["테스트를 통과한 오답 패치","비밀값 유출과 공급망 위험","검토 대기열 증가와 배포 지연"],"evidenceToResolve":["독립 회귀 테스트와 프로덕션 관측을 포함한 블라인드 평가","도구별 최소권한 정책 하의 공격 시뮬레이션","에이전트 패치의 결함 유입률·롤백률·검토시간 추적"]}],"relationshipAnalysis":[{"technologyId":"on-device-agentic-ai","relationship":"공통 에이전트 제어 루프","dependency":"두 기술 모두 목표 분해, 도구 선택, 상태 기억과 실패 복구가 필요하다. 코딩 에이전트의 저장소 탐색·검증 패턴은 온디바이스 에이전트의 제한된 도구 오케스트레이션 설계에 참고가 된다.","transferLimit":"코딩 에이전트는 재현 가능한 파일·테스트 환경과 강한 텍스트 피드백을 갖지만 온디바이스 에이전트는 지연, 전력, 센서 노이즈와 개인정보 제약을 받으므로 성공률이 그대로 전이되지 않는다."},{"technologyId":"ai-scientific-discovery","relationship":"도구 기반 장기 과제 실행","dependency":"가설 분해, 코드 실행, 결과 검증과 기록이라는 공통 루프를 사용한다. 코딩 에이전트의 감사 로그와 격리 실행 구조는 과학 에이전트의 재현성 기반이 될 수 있다.","transferLimit":"소프트웨어 테스트는 비교적 빠르고 반복 가능하지만 과학 발견은 실험 지연, 측정 오차와 인과 추론을 포함하므로 코드 패치 벤치마크의 성과만으로 연구 자율성을 판단할 수 없다."}],"technologyOutlook":{"basisDate":"2026-08-21","scope":"투자 의견이 아니라 저장소 작업 에이전트의 기술적 전개 경로다. 각 경로는 모델 점수보다 실제 변경의 검증 가능성과 운영 통제 수준으로 판정한다.","pathways":[{"label":"검증 가능한 저장소 단위 위임의 정착","horizon":"1~3년","mechanism":"명확한 수용 기준이 있는 버그 수정·테스트 보강·마이그레이션을 격리 브랜치에서 수행하고 독립 테스트와 사람 검토를 통과한 변경만 병합한다.","requiredConditions":["과제별 실행 가능한 수용 기준","비밀값이 분리된 최소권한 샌드박스","에이전트와 독립된 테스트·리뷰 경로","실패 비용을 반영한 작업 라우팅"],"observableSignals":["실제 저장소 무작위 비교에서 순완료시간 감소","사람 수정량과 롤백률의 동시 감소","보안 사고 없이 반복되는 다중 저장소 운영 자료"],"invalidationSignals":["패치 수 증가와 함께 검토 대기시간이 더 빠르게 증가","테스트 통과 후 회귀·롤백률 악화","프롬프트 인젝션 또는 권한 오남용이 반복"]},{"label":"장기 유지보수 에이전트로의 확장","horizon":"3~5년","mechanism":"세션을 넘는 저장소 기억과 변경 이력 모델을 사용해 의존성 갱신, 대규모 리팩터링, 장애 원인 수정처럼 여러 단계와 긴 피드백 주기를 가진 작업을 이어 간다.","requiredConditions":["버전이 있는 장기 기억과 근거 추적","환경 변화에 견디는 재현 가능한 평가","중간 산출물 승인과 되돌리기","프로덕션 관측 신호를 안전하게 읽는 인터페이스"],"observableSignals":["오염 방지 최신 과제에서 긴 작업 성공률 향상","수주 단위 과제의 독립 재현과 감사 가능성","장기 작업에서 토큰·시간당 실패 비용 감소"],"invalidationSignals":["오래된 기억이 현재 저장소 규칙과 충돌","장기 과제에서 목표 이탈과 비용 폭증이 지속","운영 피드백을 잘못 해석해 반복 장애를 유발"]}]},"researchAgenda":[{"priority":"P1","question":"동일한 실제 저장소 과제에서 에이전트 위임이 사람 단독 작업보다 순완료시간과 결함률을 동시에 개선하는가?","requiredEvidence":"최근 도구를 사용한 다기관 무작위 비교, 작업별 사람 시간, 검토·재작업·롤백을 포함한 원자료","decisionImpact":"제품화 진전을 단순 사용량이 아니라 실제 작업 성능 개선으로 판정한다."},{"priority":"P1","question":"독립 테스트와 최소권한 정책이 프롬프트 인젝션과 테스트 우회 실패를 어느 정도 차단하는가?","requiredEvidence":"공개 공격 시나리오, 권한별 침해 성공률, 에이전트가 보지 못한 회귀 테스트 결과","decisionImpact":"자동화 범위를 코드 제안에 제한할지 반복 운영 작업까지 넓힐지 결정한다."},{"priority":"P2","question":"장기 기억이 반복 과제의 문맥 복원 비용을 줄이면서 오래된 규칙의 오염을 피하는가?","requiredEvidence":"시간 순서가 보존된 저장소 과제와 기억 사용 여부의 교차 평가","decisionImpact":"세션형 도구에서 지속형 유지보수 에이전트로의 전환 가능성을 판정한다."}],"citations":[{"publisher":"METR","title":"Task-Completion Time Horizons of Frontier AI Models","url":"https://metr.org/time-horizons/","eventDate":"2026-05-08","publishedDate":"2026-05-08"},{"publisher":"METR","title":"Measuring the Impact of Early-2025 AI on Experienced Open-Source Developer Productivity","url":"https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/","eventDate":"2025-02-28","publishedDate":"2025-07-10"},{"publisher":"METR","title":"We are Changing our Developer Productivity Experiment Design","url":"https://metr.org/blog/2026-02-24-uplift-update/","eventDate":"2026-02-24","publishedDate":"2026-02-24"},{"publisher":"GitHub","title":"Risks and mitigations for GitHub Copilot cloud agent","url":"https://docs.github.com/en/copilot/concepts/agents/cloud-agent/risks-and-mitigations","eventDate":"미확인","publishedDate":"미확인"},{"publisher":"GitHub","title":"Copilot coding agent is now generally available","url":"https://github.blog/changelog/2025-09-25-copilot-coding-agent-is-now-generally-available/","eventDate":"2025-09-25","publishedDate":"2025-09-25"}]}'
